import http from 'http';
import { generateKeyPair, exportJWK, SignJWT } from 'jose';
import { auth } from 'express-oauth2-jwt-bearer';
import express from 'express';
import supertest from 'supertest';

async function test() {
  const { publicKey, privateKey } = await generateKeyPair('RS256');
  const jwk = await exportJWK(publicKey);
  jwk.kid = 'test-key-1';
  jwk.alg = 'RS256';
  jwk.use = 'sig';

  const server = http.createServer((req, res) => {
    if (req.url === '/.well-known/jwks.json') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ keys: [jwk] }));
      return;
    }
    res.writeHead(404);
    res.end();
  });

  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const port = server.address().port;
  const issuer = `http://127.0.0.1:${port}/`;
  const audience = 'https://keys-of-the-departed-api';

  const app = express();
  app.use(auth({
    issuerBaseURL: issuer,
    jwksUri: `http://127.0.0.1:${port}/.well-known/jwks.json`,
    audience: audience,
    tokenSigningAlg: 'RS256'
  }));
  app.get('/test', (req, res) => res.json({ ok: true, auth: req.auth }));

  const token = await new SignJWT({ permissions: ['create:investigations'] })
    .setProtectedHeader({ alg: 'RS256', kid: 'test-key-1' })
    .setIssuedAt()
    .setIssuer(issuer)
    .setAudience(audience)
    .setExpirationTime('1h')
    .sign(privateKey);

  const res = await supertest(app)
    .get('/test')
    .set('Authorization', `Bearer ${token}`);

  console.log('Status with valid token:', res.status, res.body);

  const resNoAuth = await supertest(app).get('/test');
  console.log('Status without token:', resNoAuth.status, resNoAuth.text);

  server.close();
}

test().catch(err => {
  console.error('Test error:', err);
  process.exit(1);
});

