  await collection.insertOne({ ...inv });

  return inv;
}

async listInvestigations(callerOwnerId?: string): Promise<Investigation[]> {
  const collection = this.db.collection(COLLECTIONS.INVESTIGATIONS);
  const filter = callerOwnerId
    ? { $or: [{ is_demo: true }, { owner_id: callerOwnerId }] }
    : { is_demo: true };

  const docs = await collection
    .find(filter, { projection: { _id: 0 } })
    .sort({ created_at: -1 })
    .toArray();

  const list: Investigation[] = [];
  for (const doc of docs) {
    const parsed = InvestigationSchema.safeParse(doc);
    if (parsed.success) {
      list.push(parsed.data);
    }
  }
  return list;
}

