import React, { createContext, useContext, useMemo } from "react";
import { Auth0Provider, useAuth0, AppState } from "@auth0/auth0-react";

export interface AuthUser {
  name?: string;
  email?: string;
  sub?: string;
  picture?: string;
}

export interface AuthContextValue {
  isAuthenticated: boolean;
  isLoading: boolean;
  user: AuthUser | null;
  loginWithRedirect: (options?: any) => Promise<void>;
  logout: (options?: any) => void;
  getAccessTokenSilently: (options?: any) => Promise<string>;
  isConfigured: boolean;
}

const AuthContext = createContext<AuthContextValue>({
  isAuthenticated: false,
  isLoading: false,
  user: null,
  loginWithRedirect: async () => {},
  logout: () => {},
  getAccessTokenSilently: async () => {
    throw new Error("Auth0 is not configured");
  },
  isConfigured: false,
});

export const useAuth = (): AuthContextValue => useContext(AuthContext);

const Auth0Bridge: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const auth0 = useAuth0();

  const user = useMemo<AuthUser | null>(() => {
    if (!auth0.user) return null;
    return {
      name: auth0.user.name || auth0.user.nickname,
      email: auth0.user.email,
      sub: auth0.user.sub,
      picture: auth0.user.picture,
    };
  }, [auth0.user]);

  const value = useMemo<AuthContextValue>(
    () => ({
      isAuthenticated: auth0.isAuthenticated,
      isLoading: auth0.isLoading,
      user,
      loginWithRedirect: auth0.loginWithRedirect,
      logout: auth0.logout,
      getAccessTokenSilently: auth0.getAccessTokenSilently,
      isConfigured: true,
    }),
    [auth0.isAuthenticated, auth0.isLoading, user, auth0.loginWithRedirect, auth0.logout, auth0.getAccessTokenSilently],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const AuthProviderWithHistory: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const domain = import.meta.env.VITE_AUTH0_DOMAIN;
  const clientId = import.meta.env.VITE_AUTH0_CLIENT_ID;
  const audience = import.meta.env.VITE_AUTH0_AUDIENCE;

  const isConfigured = Boolean(domain && clientId);

  const onRedirectCallback = (appState?: AppState) => {
    if (typeof window !== "undefined") {
      const target = appState?.returnTo || window.location.pathname + window.location.hash;
      window.history.replaceState({}, document.title, target);
    }
  };

  if (!isConfigured) {
    const unconfiguredValue: AuthContextValue = {
      isAuthenticated: false,
      isLoading: false,
      user: null,
      loginWithRedirect: async () => {
        console.warn("Auth0 is not configured (missing VITE_AUTH0_DOMAIN or VITE_AUTH0_CLIENT_ID)");
      },
      logout: () => {},
      getAccessTokenSilently: async () => {
        throw new Error("Auth0 is not configured in client environment");
      },
      isConfigured: false,
    };

    return <AuthContext.Provider value={unconfiguredValue}>{children}</AuthContext.Provider>;
  }

  const redirectUri = typeof window !== "undefined" ? window.location.origin : "http://localhost:3000";

  return (
    <Auth0Provider
      domain={domain}
      clientId={clientId}
      authorizationParams={{
        redirect_uri: redirectUri,
        audience: audience || undefined,
        scope: "openid profile email read:investigations create:investigations",
      }}
      onRedirectCallback={onRedirectCallback}
      useRefreshTokens={true}
      cacheLocation="memory"
    >
      <Auth0Bridge>{children}</Auth0Bridge>
    </Auth0Provider>
  );
};

import {
  CreateInvestigationInput,
  SingleFileInput,
  Investigation,
  InvestigationFindings,
} from "@keys/contracts";
import { useAuth } from "./AuthProvider.js";

export class ApiError extends Error {
  constructor(
    message: string,
    public status?: number,
    public code?: string,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

export interface ApiClient {
  createInvestigation: (input: CreateInvestigationInput) => Promise<Investigation>;
  uploadFiles: (
    investigationId: string,
    files: SingleFileInput[],
  ) => Promise<{
    investigation: Investigation;
    files: any[];
    extracted_records_count: number;
    errors: string[];
  }>;
  processInvestigation: (investigationId: string) => Promise<InvestigationFindings>;
  getInvestigation: (investigationId: string) => Promise<Investigation>;
  getInvestigationFindings: (investigationId: string) => Promise<InvestigationFindings>;
}

export function useApiClient(): ApiClient {
  const { getAccessTokenSilently, isAuthenticated } = useAuth();
  const audience = import.meta.env.VITE_AUTH0_AUDIENCE;

  const getAuthToken = async (): Promise<string> => {
    if (!isAuthenticated) {
      throw new ApiError(
        "Authentication required: Please sign in to perform this action.",
        401,
        "UNAUTHENTICATED",
      );
    }
    try {
      return await getAccessTokenSilently({
        authorizationParams: {
          audience: audience || undefined,
          scope: "openid profile email read:investigations create:investigations",
        },
      });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to acquire access token";
      throw new ApiError(`Token acquisition failed: ${msg}`, 401, "TOKEN_ACQUISITION_ERROR");
    }
  };

  const getOptionalAuthToken = async (): Promise<string | null> => {
    if (!isAuthenticated) return null;
    try {
      return await getAccessTokenSilently({
        authorizationParams: {
          audience: audience || undefined,
          scope: "openid profile email read:investigations create:investigations",
        },
      });
    } catch {
      return null;
    }
  };

  return {
    createInvestigation: async (input: CreateInvestigationInput): Promise<Investigation> => {
      const token = await getAuthToken();
      const res = await fetch("/api/investigations", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(input),
      });

      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string; message?: string };
        const msg = body.error || body.message || `Creation failed with status ${res.status}`;
        throw new ApiError(msg, res.status);
      }

      return (await res.json()) as Investigation;
    },

    uploadFiles: async (investigationId: string, files: SingleFileInput[]) => {
      const token = await getAuthToken();
      const res = await fetch(`/api/investigations/${encodeURIComponent(investigationId)}/upload`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ files }),
      });

      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string; message?: string };
        const msg = body.error || body.message || `Upload failed with status ${res.status}`;
        throw new ApiError(msg, res.status);
      }

      return await res.json();
    },

    processInvestigation: async (investigationId: string): Promise<InvestigationFindings> => {
      const token = await getAuthToken();
      const res = await fetch(`/api/investigations/${encodeURIComponent(investigationId)}/process`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string; message?: string };
        const msg = body.error || body.message || `Processing failed with status ${res.status}`;
        throw new ApiError(msg, res.status);
      }

      return (await res.json()) as InvestigationFindings;
    },

    getInvestigation: async (investigationId: string): Promise<Investigation> => {
      const token = await getOptionalAuthToken();
      const headers: Record<string, string> = {};
      if (token) {
        headers["Authorization"] = `Bearer ${token}`;
      }

      const res = await fetch(`/api/investigations/${encodeURIComponent(investigationId)}`, {
        headers,
      });

      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string; message?: string };
        const msg = body.error || body.message || `Failed to retrieve investigation (${res.status})`;
        throw new ApiError(msg, res.status);
      }

      return (await res.json()) as Investigation;
    },

    getInvestigationFindings: async (investigationId: string): Promise<InvestigationFindings> => {
      const token = await getOptionalAuthToken();
      const headers: Record<string, string> = {};
      if (token) {
        headers["Authorization"] = `Bearer ${token}`;
      }

      const res = await fetch(`/api/investigations/${encodeURIComponent(investigationId)}/findings`, {
        headers,
      });

      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string; message?: string };
        const msg =
          body.error || body.message || `Failed to retrieve investigation findings (${res.status})`;
        throw new ApiError(msg, res.status);
      }

      return (await res.json()) as InvestigationFindings;
    },
  };
}

