const handleAuth0Login = () => {
  if (isConfigured && loginWithRedirect) {
    setLoading(true);
    loginWithRedirect({
      authorizationParams: {
        screen_hint: mode === "signup" ? "signup" : undefined,
        login_hint: email.trim() || undefined,
      },
      appState: { returnTo: window.location.hash || "#/" },
    }).catch((err: unknown) => {
      setLoading(false);
      const msg = err instanceof Error ? err.message : "Failed to initiate Auth0 login";
      setErrors((prev) => ({ ...prev, email: msg }));
    });
  }
};

const handleSubmit = (e: React.FormEvent) => {
  e.preventDefault();
  if (!validateForm()) return;

  if (isConfigured) {
