// If opened with an existing investigation ID, load its findings directly
useEffect(() => {
  if (initialInvId) {
    fetch(`/api/investigations/${encodeURIComponent(initialInvId)}/findings`)
      .then(async (res) => {
        if (!res.ok) {
          // If not processed yet, try retrieving the investigation metadata
          return fetch(`/api/investigations/${encodeURIComponent(initialInvId)}`)
            .then(async (invRes) => {
              if (!invRes.ok) throw new Error("Investigation not found");
              return invRes.json() as Promise<Investigation>;
            })
            .then((inv) => {
              setInvestigation(inv);
              setCurrentStep(inv.status === "completed" ? "results" : "upload");
            });
        }
        return (res.json() as Promise<InvestigationFindings>).then((data) => {
          setFindings(data);
          setInvestigation(data.investigation);
          setCurrentStep("results");
        });
      })
      .catch((err: Error) => {
        setProcessingError(err.message || "Failed to load investigation");
      });
  }
}, [initialInvId]);

// Step 1: Create Investigation
const handleCreateInvestigation = async (e: React.FormEvent) => {
  e.preventDefault();
  setFormErrors({});

  const user = typeof window !== "undefined" ? localStorage.getItem("kotd_user") : null;
  if (!user) {
    onRouteChange("signin");
    return;
  }

  const parseResult = CreateInvestigationSchema.safeParse({ name, description });
  if (!parseResult.success) {
    const fieldErrors: { name?: string; description?: string } = {};
    parseResult.error.issues.forEach((issue) => {
      if (issue.path[0] === "name") fieldErrors.name = issue.message;
      if (issue.path[0] === "description") fieldErrors.description = issue.message;
    });
    setFormErrors(fieldErrors);
    return;
  }

  try {
    setUploading(true);
    const res = await fetch("/api/investigations", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(parseResult.data),
    });

    if (!res.ok) {
      const body = (await res.json().catch(() => ({}))) as { error?: string };
      throw new Error(body.error || "Failed to create investigation");
    }

    const created = (await res.json()) as Investigation;
    setInvestigation(created);
    setCurrentStep("upload");
    setUploading(false);
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : "Creation failed";
    setUploadError(msg);
    setUploading(false);
  }
};

