              <div>
                <label
                  htmlFor="inv-date-end"
                  style={{
                    display: "block",
                    fontFamily: "var(--display)",
                    fontSize: "10px",
                    letterSpacing: "0.08em",
                    color: "var(--gold2)",
                    marginBottom: "6px",
