                </label>
                <input
                  id="inv-date-end"
                  type="date"
                  value={dateRangeEnd}
                  onChange={(e) => setDateRangeEnd(e.target.value)}
                  style={{
                    width: "100%",
                    padding: "10px 12px",
                    background: "rgba(10, 8, 12, 0.8)",
                    border: "1px solid rgba(197, 160, 89, 0.4)",
