          </div>

          {/* Drag & Drop Zone */}
          <div
            onDragOver={(e) => {
              e.preventDefault();
              setIsDragOver(true);
            }}
            onDragLeave={() => setIsDragOver(false)}
            onDrop={(e) => {
              e.preventDefault();
              setIsDragOver(false);
              handleFilesAdded(e.dataTransfer.files);
            }}
            style={{
              padding: "44px 24px",
              textAlign: "center",
              border: isDragOver ? "2px dashed var(--gold2)" : "2px dashed var(--line)",
              background: isDragOver ? "rgba(197, 160, 89, 0.12)" : "rgba(18, 14, 20, 0.8)",
              borderRadius: "4px",
              transition: "all 0.2s ease",
            }}
          >
            <img
              src="/goldenbook.png"
              alt="Intake Records"
              style={{ width: "64px", height: "64px", objectFit: "contain", margin: "0 auto 14px", opacity: 0.9 }}
            />
            <h3 className="display" style={{ fontSize: "19px", color: "var(--gold2)", margin: "0 0 8px" }}>
              Drag &amp; Drop Engineering Records Here
            </h3>
            <p style={{ fontSize: "13px", color: "var(--muted)", maxWidth: "560px", margin: "0 auto 18px", lineHeight: 1.5 }}>
              Upload structured bundles in <strong>JSON</strong>, <strong>CSV</strong>, <strong>JSONL</strong>, or <strong>raw audit logs</strong>.
              Max 5MB per file.
            </p>

            <div style={{ display: "flex", gap: "12px", justifyContent: "center", flexWrap: "wrap" }}>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                accept=".json,.jsonl,.ndjson,.log,.txt,.csv"
                style={{ display: "none" }}
                onChange={(e) => handleFilesAdded(e.target.files)}
              />
              <button
                type="button"
                id="btn-browse-files"
                onClick={() => fileInputRef.current?.click()}
                className="btn small"
              >
                Browse Files
              </button>
              <button
                type="button"
                id="btn-load-sample-logs"
                onClick={handleLoadSampleBundle}
                className="btn secondary small"
              >
                + Load Sample Bundle (Logs &amp; CSV)
              </button>
              <button
                type="button"
                id="btn-view-schemas"
                onClick={() => setShowSchemasModal(true)}
                className="btn ghost small"
              >
                View Expected Schemas
              </button>
            </div>
          </div>

          {/* Rejected Files Alert */}
          {rejectedFiles.length > 0 && (
            <div style={{ padding: "16px 20px", background: "rgba(109,23,27,0.25)", border: "1px solid var(--crimson2)", borderRadius: "4px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "8px" }}>
                <strong style={{ color: "#f0b9ad", fontSize: "13px" }}>Rejected Files ({rejectedFiles.length})</strong>
                <button
                  type="button"
                  onClick={() => setRejectedFiles([])}
                  className="btn ghost small"
                  style={{ fontSize: "10px", padding: "2px 6px" }}
                >
                  Dismiss
                </button>
              </div>
              <ul style={{ margin: 0, paddingLeft: "18px", fontSize: "12px", color: "#e8c5be" }}>
                {rejectedFiles.map((rf, rfid) => (
                  <li key={rfid}>
                    <strong>{rf.name}</strong>: {rf.reason}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Staged Files List */}
          {stagedFiles.length > 0 ? (
            <div className="panel" style={{ padding: "24px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
                <div className="eyebrow" style={{ color: "var(--gold)" }}>
                  STAGED EVIDENCE FILES ({stagedFiles.length})
                </div>
                <span className="mono" style={{ fontSize: "11px", color: "var(--gold2)" }}>
                  Total Estimated Records: {totalEstimatedRecords}
                </span>
              </div>

              <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                {stagedFiles.map((item) => {
                  const meta = EVIDENCE_CATEGORY_META[item.category];
                  return (
                    <div
                      key={item.id}
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        padding: "12px 16px",
                        background: "rgba(0,0,0,0.35)",
                        borderRadius: "3px",
                        borderLeft: item.status === "error" ? "3px solid var(--crimson2)" : "3px solid var(--gold)",
                        gap: "14px",
                        flexWrap: "wrap",
                      }}
                    >
                      <div style={{ minWidth: "200px" }}>
                        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                          <span style={{ fontWeight: 600, color: "#f7ebd2", fontSize: "13.5px" }}>
                            {item.file.name}
                          </span>
                          <span className={`tag ${item.status === "error" ? "red" : item.status === "warning" ? "gold" : "green"}`} style={{ fontSize: "10px" }}>
                            {item.status.toUpperCase()}
                          </span>
                        </div>
                        <div style={{ fontSize: "11px", color: "var(--muted)", marginTop: "2px" }}>
                          Size: {(item.file.size / 1024).toFixed(1)} KB ✦ Detected: <strong>{meta.label}</strong>
                          {item.recordEstimate > 0 ? ` ✦ ~${item.recordEstimate} records` : ""}
                        </div>
                        {item.errorMessage && (
                          <div style={{ color: "var(--crimson2)", fontSize: "11.5px", marginTop: "4px" }}>
                            {item.errorMessage}
                          </div>
                        )}
                      </div>

                      <button
                        type="button"
                        onClick={() => handleRemoveFile(item.id)}
                        className="btn ghost small"
                        style={{ color: "var(--crimson2)", fontSize: "11px" }}
