              </div>

              <div style={{ marginTop: "24px", display: "flex", justifyContent: "flex-end", gap: "12px" }}>
                <button
                  type="button"
                  id="btn-proceed-to-config"
                  onClick={() => setCurrentStep("config")}
                  disabled={validFilesCount === 0}
                  className="btn"
                  style={{ padding: "12px 28px", fontSize: "12px" }}
                >
                  Configure Investigation Scope →
                </button>
              </div>
            </div>
          ) : (
            <div style={{ textAlign: "center", padding: "20px", color: "var(--muted)", fontSize: "13px" }}>
              No files staged yet. Add files above or load the sample demonstration bundle to continue.
            </div>
          )}
        </div>
      )}

      {/* ======================================================== */}
      {/* STEP 3: CONFIGURATION                                    */}
      {/* ======================================================== */}
      {currentStep === "config" && (
        <div className="panel" style={{ padding: "40px", maxWidth: "780px", margin: "0 auto" }}>
          <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "8px" }}>
            STEP 3 OF 5 · INVESTIGATION CONFIGURATION
          </div>
          <h2 className="display" style={{ fontSize: "24px", color: "var(--cream)", margin: "0 0 10px" }}>
            Configure Analysis Parameters
          </h2>
          <p className="serif" style={{ fontSize: "15px", color: "#c7b591", fontStyle: "italic", marginBottom: "28px", lineHeight: 1.5 }}>
            Customize detection heuristics. Only parameters supported by the deterministic verifier and
            activity models are presented here.
          </p>

          <div style={{ marginBottom: "28px" }}>
            <label
              htmlFor="cfg-inactivity"
              style={{
                display: "block",
                fontFamily: "var(--display)",
                fontSize: "11px",
                letterSpacing: "0.08em",
                color: "var(--gold2)",
                marginBottom: "6px",
              }}
            >
              INACTIVITY THRESHOLD (DAYS)
            </label>
            <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
              <input
                id="cfg-inactivity"
                type="number"
                min={1}
                max={365}
                value={inactivityDays}
                onChange={(e) => setInactivityDays(Number(e.target.value) || 90)}
                style={{
                  width: "120px",
                  padding: "10px 14px",
                  background: "rgba(10, 8, 12, 0.8)",
                  border: "1px solid rgba(197, 160, 89, 0.4)",
                  color: "#f7ebd2",
                  borderRadius: "3px",
                  fontSize: "14px",
                }}
              />
              <span style={{ fontSize: "12.5px", color: "#c8b994" }}>
                Default: <strong>90 days</strong>. Machine identities with no recorded activity exceeding this threshold are flagged as <em>Lonely / Inactive Keys</em>.
              </span>
            </div>
          </div>

          <div style={{ marginBottom: "28px" }}>
            <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "10px" }}>
              EVIDENCE CATEGORIES INCLUDED
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
              {(Object.keys(EVIDENCE_CATEGORY_META) as EvidenceCategory[]).map((catKey) => {
                const meta = EVIDENCE_CATEGORY_META[catKey];
                const isChecked = enabledCategories[catKey];
                return (
                  <label
                    key={catKey}
                    style={{
                      display: "flex",
                      alignItems: "flex-start",
                      gap: "10px",
                      padding: "10px 14px",
                      background: isChecked ? "rgba(197, 160, 89, 0.1)" : "rgba(0, 0, 0, 0.2)",
                      border: `1px solid ${isChecked ? "var(--gold)" : "var(--line)"}`,
                      borderRadius: "3px",
                      cursor: "pointer",
                    }}
                  >
                    <input
                      type="checkbox"
                      checked={isChecked}
                      onChange={(e) =>
                        setEnabledCategories((prev) => ({ ...prev, [catKey]: e.target.checked }))
                      }
                      style={{ marginTop: "3px" }}
                    />
                    <div>
                      <div style={{ fontSize: "12.5px", fontWeight: 600, color: "#f7ebd2" }}>
                        {meta.label}
                      </div>
                      <div style={{ fontSize: "11px", color: "var(--muted)", marginTop: "2px" }}>
                        {meta.description}
                      </div>
                    </div>
                  </label>
                );
              })}
            </div>
          </div>

          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "32px" }}>
            <button
              type="button"
              onClick={() => setCurrentStep("upload")}
              className="btn secondary small"
            >
              ← Back to Upload
            </button>
            <button
              type="button"
              id="btn-proceed-to-validate"
              onClick={() => setCurrentStep("validate")}
              className="btn"
              style={{ padding: "12px 28px", fontSize: "12px" }}
            >
              Review Pre-Flight Summary →
            </button>
          </div>
        </div>
      )}

      {/* ======================================================== */}
      {/* STEP 4: PRE-FLIGHT VALIDATION & SUMMARY                  */}
      {/* ======================================================== */}
      {currentStep === "validate" && (
        <div className="panel" style={{ padding: "40px", maxWidth: "820px", margin: "0 auto" }}>
          <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "8px" }}>
            STEP 4 OF 5 · PRE-FLIGHT AUDIT VALIDATION
          </div>
          <h2 className="display" style={{ fontSize: "24px", color: "var(--cream)", margin: "0 0 10px" }}>
            Validate Staged Evidence Bundle
          </h2>
          <p className="serif" style={{ fontSize: "15px", color: "#c7b591", fontStyle: "italic", marginBottom: "26px" }}>
            Verify that your evidence bundle is complete and meets strict verification requirements before running the audit.
          </p>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: "16px", marginBottom: "28px" }}>
            <div style={{ padding: "16px", background: "rgba(0,0,0,0.3)", borderRadius: "3px", borderLeft: "3px solid var(--gold)" }}>
              <div className="eyebrow" style={{ fontSize: "10px", color: "var(--gold)" }}>STAGED FILES</div>
              <div className="mono" style={{ fontSize: "24px", fontWeight: 700, color: "var(--cream)", marginTop: "4px" }}>
                {validFilesCount}
              </div>
            </div>

            <div style={{ padding: "16px", background: "rgba(0,0,0,0.3)", borderRadius: "3px", borderLeft: "3px solid var(--blue)" }}>
              <div className="eyebrow" style={{ fontSize: "10px", color: "var(--blue)" }}>ESTIMATED RECORDS</div>
              <div className="mono" style={{ fontSize: "24px", fontWeight: 700, color: "var(--cream)", marginTop: "4px" }}>
                ~{totalEstimatedRecords}
              </div>
            </div>

            <div style={{ padding: "16px", background: "rgba(0,0,0,0.3)", borderRadius: "3px", borderLeft: "3px solid var(--green)" }}>
              <div className="eyebrow" style={{ fontSize: "10px", color: "var(--green)" }}>INACTIVITY GAP</div>
              <div className="mono" style={{ fontSize: "24px", fontWeight: 700, color: "var(--cream)", marginTop: "4px" }}>
                {inactivityDays}d
              </div>
            </div>
          </div>

          <div style={{ marginBottom: "28px" }}>
            <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "10px" }}>
              AVAILABLE EVIDENCE CATEGORIES
            </div>
            <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
              {availableCategories.map((cat) => (
                <span key={cat} className="tag green" style={{ fontSize: "11px" }}>
                  ✓ {EVIDENCE_CATEGORY_META[cat].label}
                </span>
              ))}
              {availableCategories.length === 0 && (
                <span className="tag red">No valid evidence categories detected</span>
              )}
            </div>
          </div>

          <div style={{ padding: "16px", background: "rgba(197, 160, 89, 0.08)", border: "1px solid var(--gold)", borderRadius: "3px", marginBottom: "32px", fontSize: "12.5px", color: "#e8d5b5", lineHeight: 1.55 }}>
            <strong>Analysis Architecture Notice:</strong> Proposes candidate machine identities and ownership hypotheses citing verbatim record substrings. Deterministic verification rejects ungrounded claims with reason codes R1–R5. No automated production credential revocation.
          </div>

          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <button
              type="button"
              onClick={() => setCurrentStep("config")}
              className="btn secondary small"
            >
              ← Back to Config
            </button>
            <button
              type="button"
              id="btn-process-investigation"
              onClick={handleExecuteProcessing}
              disabled={validFilesCount === 0}
              className="btn"
              style={{
                padding: "14px 32px",
                fontSize: "12.5px",
                letterSpacing: "0.12em",
                background: "linear-gradient(180deg, #b02638, #69131f)",
                borderColor: "var(--gold2)",
              }}
            >
              ✦ RUN INVESTIGATION ANALYSIS
            </button>
          </div>
        </div>
      )}

      {/* ======================================================== */}
      {/* STEP 5: PROCESSING SPINNER                               */}
      {/* ======================================================== */}
      {currentStep === "processing" && (
        <div
          className="panel"
          style={{
            padding: "54px 30px",
            textAlign: "center",
            border: "1px dashed var(--gold)",
            background: "rgba(18, 14, 20, 0.95)",
            maxWidth: "680px",
            margin: "40px auto",
          }}
        >
          <img
            src="/candleon.png"
            alt="Lighting Candle"
            className="candle-glow"
            style={{ width: "32px", height: "54px", margin: "0 auto 16px", objectFit: "contain" }}
          />
          <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "8px" }}>
            EXECUTING INVESTIGATION PIPELINE
          </div>
          <h2 className="display" style={{ fontSize: "22px", color: "var(--cream)", margin: "0 0 12px" }}>
            Reconstructing Machine Identity Lineage...
          </h2>
          <p className="serif" style={{ color: "#c7b591", fontStyle: "italic", maxWidth: "520px", margin: "0 auto", lineHeight: 1.5 }}>
            Uploading source records, extracting candidate credentials, and performing deterministic
            substring verification with reason codes R1–R5.
          </p>
        </div>
      )}

      {/* ======================================================== */}
      {/* STEP 5: COMPREHENSIVE INVESTIGATION RESULTS              */}
      {/* ======================================================== */}
      {currentStep === "results" && findings && (
        <div style={{ display: "flex", flexDirection: "column", gap: "28px" }}>
          {/* Header Card */}
          <div
            className="panel"
            style={{
              padding: "36px",
              border: "1px solid var(--gold)",
              backgroundImage: "linear-gradient(135deg, rgba(35,26,20,0.98), rgba(16,13,11,0.96))",
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: "20px" }}>
              <div>
                <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "6px" }}>
                  INVESTIGATION FINDINGS REPORT ✦ {findings.investigation.investigation_id}
                </div>
                <h1 className="display" style={{ fontSize: "28px", color: "var(--cream)", margin: "4px 0 10px" }}>
                  {findings.investigation.name}
                </h1>
                <p style={{ fontSize: "14px", color: "#c7b591", margin: 0, fontStyle: "italic" }}>
                  {findings.investigation.description || "Machine identity audit investigation."}
                </p>
              </div>

              <div style={{ display: "flex", gap: "10px", alignItems: "center", flexWrap: "wrap" }}>
                <span className="tag green">STATUS: COMPLETED</span>
                <span className="tag gray">RECORDS: {findings.processing_summary.total_records_processed}</span>
                <span className="tag gold">IDENTITIES: {findings.discovered_accounts.length}</span>
              </div>
            </div>

            {/* Architecture Transparency Banner */}
            <div
              style={{
                marginTop: "24px",
                padding: "14px 18px",
                background: "rgba(0,0,0,0.4)",
                borderRadius: "3px",
                borderLeft: "3px solid var(--blue)",
                fontSize: "12.5px",
                color: "#d0bd98",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
                gap: "10px",
              }}
            >
              <div>
                <strong style={{ color: "#f0dfbd" }}>Deterministic Verification Engine:</strong> Every
                claim is verified against source audit records. Claims failing exact quote or entity checks
                are quarantined with reason codes R1–R5.
              </div>
              <span className="tag gray" style={{ fontSize: "10px" }}>
                CLAIMS VERIFIED: {findings.processing_summary.claims_verified_count} | QUARANTINED:{" "}
                {findings.processing_summary.claims_quarantined_count}
              </span>
            </div>
          </div>

          {/* Core Answers Section: Answering the 5 Essential Questions */}
          <div className="panel" style={{ padding: "28px" }}>
            <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "6px" }}>
              DISCOVERED MACHINE IDENTITIES &amp; INVESTIGATION ANSWERS
            </div>
            <h3 className="display" style={{ fontSize: "20px", color: "var(--cream)", margin: "0 0 20px" }}>
              Machine Identity Findings ({findings.discovered_accounts.length})
            </h3>

            {findings.discovered_accounts.length === 0 ? (
              <div style={{ padding: "36px", textAlign: "center", border: "1px dashed var(--line)", borderRadius: "4px" }}>
                <p style={{ color: "var(--muted)", margin: 0, fontStyle: "italic" }}>
                  No machine identity records were detected in the uploaded evidence.
                </p>
              </div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
                {findings.discovered_accounts.map((acc) => {
                  const matchingCase = findings.cases.find((c) => c.account_id === acc.account_id);
                  const isVerified = acc.owner_status === "verified";
                  const isSupported = acc.owner_status === "supported";
                  const isConflicting = acc.owner_status === "conflicting";

                  return (
                    <div
                      key={acc.account_id}
                      style={{
                        padding: "24px",
                        background: "rgba(10, 8, 12, 0.7)",
                        border: "1px solid rgba(197, 160, 89, 0.3)",
                        borderRadius: "4px",
                      }}
                    >
                      {/* Identity Header */}
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: "12px", marginBottom: "16px" }}>
                        <div>
                          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
