                      </div>

                      {/* 5 Questions Grid */}
                      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: "16px", background: "rgba(0,0,0,0.3)", padding: "16px", borderRadius: "3px", fontSize: "13px" }}>
