                              <span>
                                <em>No verified human owner</em>{" "}
                                <span className="tag red" style={{ fontSize: "9px" }}>ORPHANED</span>
                              </span>
                            )}
                          </div>
                          {acc.purpose && (
                            <div style={{ fontSize: "12px", color: "#c8b994", marginTop: "6px" }}>
                              <strong>Purpose:</strong> {acc.purpose}
                            </div>
                          )}
