                          <div className="eyebrow" style={{ fontSize: "9.5px", color: "var(--gold)" }}>4. RECORDED PERMISSIONS &amp; ACTIVITY</div>
                          <div style={{ marginTop: "4px", display: "flex", gap: "4px", flexWrap: "wrap" }}>
                            {acc.permissions.map((p, pidx) => (
                              <span key={pidx} className="tag gray" style={{ fontSize: "10px" }}>{p}</span>
                            ))}
                          </div>
                          <div style={{ fontSize: "11.5px", color: "var(--muted)", marginTop: "6px" }}>
                            Last Active: {acc.last_used_at ? new Date(acc.last_used_at).toLocaleDateString() : "Never recorded"}
                          </div>
                        </div>

                        {/* 5. Review & Reason Codes */}
                        <div>
                          <div className="eyebrow" style={{ fontSize: "9.5px", color: "var(--gold)" }}>5. HUMAN REVIEW &amp; RECOMMENDATION</div>
                          {matchingCase && matchingCase.claims_removed.length > 0 ? (
                            <div style={{ marginTop: "4px", color: "#f0b9ad", fontSize: "12px" }}>
                              <strong>Quarantined Claims ({matchingCase.claims_removed.length}):</strong>
                              {matchingCase.claims_removed.map((rc, rcidx) => (
                                <div key={rcidx} style={{ marginTop: "2px" }}>
                                  Reason Code <strong>{rc.reason_code}</strong>: {rc.text}
                                </div>
                              ))}
                            </div>
                          ) : (
                            <div style={{ marginTop: "4px", color: "#b9e2b0", fontSize: "12px" }}>
                              ✓ All proposed claims satisfied deterministic checks.
                            </div>
                          )}
                          <div style={{ fontSize: "12px", color: "var(--gold2)", marginTop: "6px" }}>
                            <strong>Next Step:</strong>{" "}
                            {isVerified
                              ? "Verify if departed owner requires key transfer to designated successor."
