                                ? "Conduct manual ownership audit with repository maintainers."
                                : "Quarantine or rotate credential; investigate ungrounded token."}
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Schemas Documentation Modal */}
      {showSchemasModal && (
        <div
