                ✕
              </button>
            </div>

            <h3 className="display" style={{ fontSize: "20px", color: "var(--cream)", marginBottom: "14px" }}>
              Expected File Formats &amp; Examples
            </h3>

            <div style={{ display: "flex", flexDirection: "column", gap: "16px", fontSize: "12.5px" }}>
              <div>
                <strong>1. Machine Identity Inventory (CSV):</strong>
                <pre style={{ background: "rgba(0,0,0,0.5)", padding: "10px", borderRadius: "3px", overflowX: "auto", color: "#d0e4ff" }}>
                  {`account_id,kind,permissions,tags,last_used_at\nacc_deploy_key_881,deploy_key,"repo:write,deploy:staging","ci,nightly",2025-04-12T10:15:30Z\nacc_service_runner_404,service_account,"cluster:admin,vault:read","daemon,sync",2024-11-03T08:15:00Z`}
                </pre>
              </div>

              <div>
                <strong>2. Engineering Tickets &amp; Audit Logs (JSON):</strong>
                <pre style={{ background: "rgba(0,0,0,0.5)", padding: "10px", borderRadius: "3px", overflowX: "auto", color: "#d0e4ff" }}>
                  {`[\n  {\n    "record_id": "rec_ticket_1092",\n    "type": "ticket",\n    "ts": "2025-04-10T14:22:00Z",\n    "author_handle": "cmendez",\n    "actor_account_id": "acc_deploy_key_881",\n    "content": "Automated night-build key for staging cluster."\n  }\n]`}
                </pre>
              </div>

              <div>
                <strong>3. Git Commit Logs (.log / .txt):</strong>
                <pre style={{ background: "rgba(0,0,0,0.5)", padding: "10px", borderRadius: "3px", overflowX: "auto", color: "#d0e4ff" }}>
                  {`commit 8f92ab018442bc014aef72948c21a4f00123\nAuthor: Carlos Mendez <cmendez@internal.corp>\nDate: Sat Apr 12 10:15:30 2025 -0400\n\n    Add staging deploy key acc_deploy_key_881`}
                </pre>
              </div>
            </div>

            <div style={{ marginTop: "24px", textAlign: "right" }}>
              <button
                type="button"
                onClick={() => setShowSchemasModal(false)}
                className="btn small"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from "react";
import { DashboardStats } from "@keys/contracts";
import { useApiClient } from "../auth/apiClient.js";

export interface DashboardPageProps {
  onRouteChange: (route: string, params?: Record<string, string>) => void;
  onOpenDemo?: () => void;
  isDemoMode?: boolean;
}

export const DashboardPage: React.FC<DashboardPageProps> = ({
  onRouteChange,
  onOpenDemo,
  isDemoMode = false,
}) => {
  const api = useApiClient();
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const fetchDashboardStats = () => {
    setLoading(true);
    setError(null);

    api
      .getDashboardStats(isDemoMode)
      .then((data) => {
        setStats(data);
        setLoading(false);
      })
      .catch((err: Error) => {
        setError(err.message || "Failed to load dashboard statistics");
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchDashboardStats();
  }, [isDemoMode]);

  if (loading) {
    return (
      <div
        className="animate-fade-in"
        style={{ maxWidth: "1340px", margin: "40px auto", padding: "0 clamp(16px, 3vw, 32px)" }}
      >
        <div
          className="panel"
          style={{
            padding: "54px 30px",
            textAlign: "center",
            border: "1px dashed var(--gold)",
            background: "rgba(18, 14, 20, 0.95)",
          }}
        >
          <img
            src="/candleon.png"
            alt="Lighting Sanctuary"
            className="candle-glow"
            style={{ width: "32px", height: "54px", margin: "0 auto 18px", objectFit: "contain" }}
          />
          <div className="eyebrow" style={{ color: "var(--gold)", marginBottom: "8px" }}>
            SYNCHRONIZING INVESTIGATOR REGISTRY
          </div>
          <h2 className="display" style={{ fontSize: "22px", color: "var(--cream)", margin: 0 }}>
            Querying Machine Identity Registry &amp; Investigation History...
          </h2>
        </div>
      </div>
    );
  }

  if (error || !stats) {
    return (
      <div
        className="animate-fade-in"
        style={{ maxWidth: "1340px", margin: "40px auto", padding: "0 clamp(16px, 3vw, 32px)" }}
      >
        <div
          className="panel"
          style={{
            padding: "48px 30px",
            textAlign: "center",
            border: "1px solid var(--crimson2)",
            background: "rgba(35, 14, 18, 0.95)",
          }}
        >
          <img
            src="/seal-broken.png"
            alt="Broken Seal"
            style={{ width: "54px", height: "54px", margin: "0 auto 16px", objectFit: "contain" }}
          />
          <div className="eyebrow" style={{ color: "var(--crimson2)", marginBottom: "8px" }}>
            REGISTRY OUTAGE
          </div>
          <h2 className="display" style={{ fontSize: "22px", color: "#f6e4bd", margin: "0 0 12px" }}>
