import React, { useState, useEffect, useRef } from "react";
import { FourChambersPreview } from "../components/FourChambersPreview.js";

export interface LandingPageProps {
  onRouteChange: (route: string, params?: Record<string, string>) => void;
  onOpenDemo: () => void;
}

const HUNTER_DIALOGUE_LINES = [
  "Welcome, investigator.",
  "The engineer may have departed, but their machine identities remain.",
  "Every forgotten key has a history. Every permission deserves scrutiny.",
  "Tell me... are you a Free Spirit?",
  "If you seek answers, open the Golden Book.",
];
const FULL_HUNTER_DIALOGUE = HUNTER_DIALOGUE_LINES.join("\n\n");

const EMERGING_WORDS = [
  { text: "acc_deploy_key", dx: -22, delay: 0 },
  { text: "iam:root_token", dx: 18, delay: 1.2 },
  { text: "service_account", dx: -12, delay: 2.4 },
  { text: "retained_access", dx: 26, delay: 3.6 },
];

export const LandingPage: React.FC<LandingPageProps> = ({ onRouteChange, onOpenDemo }) => {
  const [isHunterActive, setIsHunterActive] = useState<boolean>(false);
  const [typedDialogue, setTypedDialogue] = useState<string>("");
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const hasTriggeredNarrationRef = useRef<boolean>(false);
  const typewriterTimerRef = useRef<NodeJS.Timeout | null>(null);

  // Stop speech on page unmount
  useEffect(() => {
    return () => {
      if (typeof window !== "undefined" && window.speechSynthesis) {
        window.speechSynthesis.cancel();
      }
      if (typewriterTimerRef.current) {
        clearInterval(typewriterTimerRef.current);
      }
    };
  }, []);

  const startHunterNarration = () => {
    if (hasTriggeredNarrationRef.current) return;
    hasTriggeredNarrationRef.current = true;
    setIsHunterActive(true);

    // Cancel any ongoing speech
    if (typeof window !== "undefined" && window.speechSynthesis) {
      window.speechSynthesis.cancel();
    }

    // Typewriter effect
    setTypedDialogue("");
    if (typewriterTimerRef.current) clearInterval(typewriterTimerRef.current);
    let charIndex = 0;
    typewriterTimerRef.current = setInterval(() => {
      charIndex += 2;
      if (charIndex >= FULL_HUNTER_DIALOGUE.length) {
        setTypedDialogue(FULL_HUNTER_DIALOGUE);
        if (typewriterTimerRef.current) clearInterval(typewriterTimerRef.current);
      } else {
        setTypedDialogue(FULL_HUNTER_DIALOGUE.slice(0, charIndex));
      }
    }, 25);

    // Speech synthesis
    if (!isMuted && typeof window !== "undefined" && "speechSynthesis" in window) {
      try {
        const utterance = new SpeechSynthesisUtterance(FULL_HUNTER_DIALOGUE);
        utterance.rate = 0.92;
        utterance.pitch = 0.9;
        utterance.lang = "en-US";
        window.speechSynthesis.speak(utterance);
      } catch {
        // Graceful fallback if speech synthesis fails
      }
    }
  };

  const stopHunterNarration = () => {
    hasTriggeredNarrationRef.current = false;
    setIsHunterActive(false);
    if (typewriterTimerRef.current) {
      clearInterval(typewriterTimerRef.current);
    }
    if (typeof window !== "undefined" && window.speechSynthesis) {
      window.speechSynthesis.cancel();
    }
  };

  const toggleSound = (e: React.MouseEvent) => {
    e.stopPropagation();
    const nextMuted = !isMuted;
    setIsMuted(nextMuted);
    if (nextMuted) {
      if (typeof window !== "undefined" && window.speechSynthesis) {
        window.speechSynthesis.cancel();
      }
    } else if (isHunterActive) {
      if (typeof window !== "undefined" && "speechSynthesis" in window) {
        const utterance = new SpeechSynthesisUtterance(FULL_HUNTER_DIALOGUE);
        utterance.rate = 0.92;
        utterance.pitch = 0.9;
        utterance.lang = "en-US";
        window.speechSynthesis.speak(utterance);
      }
    }
  };

  const handleHunterClick = () => {
    stopHunterNarration();
    onRouteChange("spirit");
  };

  const handleBookClick = () => {
    stopHunterNarration();
    onRouteChange("archive", { demo: "true" });
  };

  return (
    <div className="animate-fade-in" style={{ width: "100%", overflowX: "hidden" }}>
      {/* ============================================================== */}
      {/* 1. RESTORED VISUAL HERO: HUNTER, GOLDEN BOOK & GOTHIC DEPTH */}
      {/* ============================================================== */}
      <section
        style={{
          position: "relative",
          minHeight: "calc(100vh - 86px)",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "50px clamp(20px, 5vw, 80px)",
          overflow: "visible",
          borderBottom: "1px solid var(--line)",
          background: "#0d0d11",
        }}
      >
        {/* Architectural atmospheric background */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage: `linear-gradient(90deg, rgba(13,13,17,0.96) 0%, rgba(13,13,17,0.72) 48%, rgba(13,13,17,0.88) 100%), url('/landing.png')`,
            backgroundSize: "cover",
            backgroundPosition: "center right",
            opacity: 0.92,
            zIndex: 1,
          }}
        />

        {/* Hero Left: Narrative & Call to Action */}
        <div
          style={{
            position: "relative",
            zIndex: 2,
            maxWidth: "620px",
            flex: "1 1 540px",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "12px",
              marginBottom: "18px",
            }}
          >
            <img
              src="/logo.png"
              alt="Keys of the Departed emblem"
              style={{
                width: "42px",
                height: "46px",
                objectFit: "contain",
                filter: "drop-shadow(0 0 10px rgba(197, 160, 89, 0.4))",
              }}
            />
            <div className="eyebrow" style={{ color: "var(--gold)", letterSpacing: "0.2em" }}>
              ✦ DÍA DE LOS MUERTOS MACHINE IDENTITY ARCHIVE ✦
            </div>
          </div>

          <h1 style={{ marginBottom: "20px", lineHeight: 1.08 }}>
            <span
              className="display"
              style={{
                display: "block",
                fontSize: "clamp(32px, 4.4vw, 54px)",
                fontWeight: 700,
                color: "#f7ebd2",
                letterSpacing: "0.06em",
                textTransform: "uppercase",
                textShadow: "0 4px 30px rgba(0, 0, 0, 0.95), 0 0 20px rgba(197, 160, 89, 0.2)",
              }}
            >
              THE ENGINEER IS GONE.
            </span>
            <span
              className="serif"
              style={{
                display: "block",
                fontSize: "clamp(26px, 3.6vw, 42px)",
                fontWeight: 500,
                color: "var(--gold2)",
                fontStyle: "italic",
                letterSpacing: "0.02em",
                marginTop: "6px",
                textShadow: "0 2px 14px rgba(0, 0, 0, 0.8)",
              }}
            >
              The keys remain.
            </span>
          </h1>

          <p
            className="serif"
            style={{
              fontSize: "clamp(18px, 2.1vw, 22px)",
              lineHeight: 1.55,
              color: "#e8d5b5",
              marginBottom: "14px",
              maxWidth: "580px",
            }}
          >
            Investigate forgotten machine identities, stale deploy keys, CI/CD tokens, and orphaned
            automation accounts using uploaded engineering evidence.
          </p>

          <p
            style={{
              fontSize: "14px",
              lineHeight: 1.65,
              color: "#cdb78e",
              marginBottom: "32px",
              maxWidth: "540px",
            }}
          >
            When engineers depart or change responsibilities, their human accounts are revoked, but
            automated credentials often linger with retained privileges. Keys of the Departed
            reconstructs identity ownership, verifies purpose from source commits and logs, and
            prioritizes unmanaged access for security investigators.
          </p>

          {/* Clean CTA Hierarchy: Start Investigation vs Explore Synthetic Demo */}
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: "14px",
              alignItems: "center",
              marginBottom: "16px",
            }}
          >
            <button
              type="button"
              id="cta-start-investigation"
              onClick={() => {
                stopHunterNarration();
                onRouteChange("new-investigation");
              }}
              className="btn"
              style={{
                padding: "16px 34px",
                fontSize: "12px",
                letterSpacing: "0.12em",
                background: "linear-gradient(180deg, #b02638, #69131f)",
                borderColor: "var(--gold2)",
                boxShadow: "0 0 24px rgba(197, 160, 89, 0.35)",
              }}
            >
              ✦ START AN INVESTIGATION <span>→</span>
            </button>

            <button
              type="button"
              id="cta-explore-demo"
              onClick={() => {
                stopHunterNarration();
                onRouteChange("archive", { demo: "true" });
              }}
              className="btn secondary"
              style={{
                padding: "16px 28px",
                fontSize: "12px",
                letterSpacing: "0.1em",
              }}
            >
              EXPLORE SYNTHETIC DEMO
            </button>
          </div>

          <button
            type="button"
            id="cta-guided-tour"
            onClick={() => {
              stopHunterNarration();
              onOpenDemo();
            }}
            className="serif"
            style={{
              background: "transparent",
              border: "none",
              color: "var(--gold2)",
              fontSize: "14.5px",
              fontStyle: "italic",
              cursor: "pointer",
              padding: "4px 0",
              textDecoration: "underline",
              textUnderlineOffset: "4px",
            }}
          >
            First time here? Take the guided demonstration tour ✦
          </button>

          {/* Trust Banner Note */}
          <div
            style={{
              marginTop: "36px",
              display: "flex",
              alignItems: "center",
              gap: "10px",
              fontSize: "11px",
              fontFamily: "var(--mono)",
              color: "#a99b82",
              letterSpacing: "0.08em",
            }}
          >
            <span style={{ color: "var(--gold)" }}>✓</span>
            <span>
              ZERO PRODUCTION MUTATION · EVIDENCE-GROUNDED CITATIONS · DETERMINISTIC REASON CODES
            </span>
          </div>
        </div>

        {/* Hero Right: Interactive Hunter Narrator & Golden Book Duo */}
        <div
          className="hero-art"
          style={{
            flex: "1 1 500px",
            maxWidth: "560px",
          }}
        >
          <div className="hero-duo-container">
            {/* 1. Interactive Hunter (Narrator & Free Spirit trigger) */}
            <div
              className="hunter-interactive-wrapper"
              id="interactive-hunter-trigger"
              tabIndex={0}
              role="button"
              aria-label="The Archive Hunter - Listen to narration or click to discover if you are a Free Spirit"
              onMouseEnter={startHunterNarration}
              onFocus={startHunterNarration}
              onMouseLeave={stopHunterNarration}
              onBlur={stopHunterNarration}
              onClick={handleHunterClick}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  handleHunterClick();
                }
              }}
            >
              {isHunterActive && (
                <div
                  className="hunter-dialogue-panel animate-fade-in"
                  id="hunter-dialogue-box"
                  onClick={(e) => e.stopPropagation()}
                >
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      borderBottom: "1px solid rgba(197, 160, 89, 0.3)",
                      paddingBottom: "8px",
                      marginBottom: "12px",
                    }}
                  >
                    <div className="eyebrow" style={{ color: "var(--gold)", fontSize: "10px" }}>
                      ✦ THE KEEPER&apos;S VOICE ✦
                    </div>
                    <button
                      type="button"
                      id="hunter-sound-toggle"
                      onClick={toggleSound}
                      aria-label={isMuted ? "Unmute Hunter narration" : "Mute Hunter narration"}
                      style={{
                        background: "rgba(197, 160, 89, 0.15)",
                        border: "1px solid var(--gold)",
                        borderRadius: "3px",
                        color: "var(--gold2)",
                        cursor: "pointer",
                        fontSize: "12px",
                        padding: "2px 8px",
                        display: "flex",
                        alignItems: "center",
                        gap: "4px",
                      }}
                    >
                      <span>{isMuted ? "🔇" : "🔊"}</span>
                      <span style={{ fontSize: "10px", fontFamily: "var(--mono)" }}>
                        {isMuted ? "MUTED" : "VOICE ON"}
                      </span>
                    </button>
                  </div>

                  <div
                    className="serif"
                    id="hunter-dialogue-text"
                    style={{
                      fontSize: "15px",
                      lineHeight: 1.6,
                      color: "#f7ebd2",
                      whiteSpace: "pre-line",
                      fontStyle: "italic",
                      minHeight: "110px",
                    }}
                  >
                    {typedDialogue}
                    {typedDialogue.length < FULL_HUNTER_DIALOGUE.length && (
                      <span style={{ animation: "pulse 0.8s infinite", color: "var(--gold)" }}>
                        |
                      </span>
                    )}
                  </div>

                  <div
                    style={{
                      marginTop: "12px",
                      borderTop: "1px dashed rgba(197, 160, 89, 0.25)",
                      paddingTop: "8px",
                      fontSize: "11px",
                      fontFamily: "var(--mono)",
                      color: "var(--gold2)",
                      textAlign: "right",
                    }}
                  >
                    Click to discover if you are a Free Spirit →
                  </div>
                </div>
              )}

              <img
                src="/hunter.png"
                alt="The Archive Keeper holding a gilded ledger"
                className="hunter-art"
                id="hunter-character-image"
              />
            </div>

            {/* 2. Interactive Golden Book in Foreground with Emerging Words */}
            <div
              className="book-interactive-wrapper"
              id="interactive-book-trigger"
              tabIndex={0}
              role="button"
              aria-label="Open the Golden Book - Explore the Synthetic Machine Identity Archive"
              onClick={handleBookClick}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  handleBookClick();
                }
              }}
            >
              {/* Emerging Ethereal Words from Book Pages */}
              {EMERGING_WORDS.map((w, idx) => (
                <span
                  key={idx}
                  className="emerging-word"
                  style={{
                    bottom: "75%",
                    left: "35%",
                    ["--dx" as string]: `${w.dx}px`,
                    animationDelay: `${w.delay}s`,
                  }}
                >
                  {w.text}
                </span>
              ))}

              <img
                src="/goldenbook.png"
                alt="The Golden Archive Ledger"
                className="hero-book"
                id="golden-book-image"
              />

              <span className="book-hover-label" id="book-hover-label">
                ✦ Open the Golden Book ✦
              </span>
            </div>
          </div>
        </div>
      </section>

