/* Hero Visual Identity Art & Interactive Elements */
.hero-art {
  position: relative;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-height: 520px;
  width: 100%;
}

.hero-duo-container {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  position: relative;
  width: 100%;
  min-height: 500px;
}

/* 1. Interactive Hunter */
.hunter-interactive-wrapper {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
  z-index: 3;
}

.hunter-interactive-wrapper:hover .hunter-art,
.hunter-interactive-wrapper:focus-visible .hunter-art {
  filter: drop-shadow(0 18px 50px rgba(0, 0, 0, 0.95))
    drop-shadow(0 0 32px rgba(240, 213, 154, 0.65)) drop-shadow(0 0 50px rgba(139, 30, 45, 0.35));
  transform: translateY(-6px) scale(1.02);
}

.hunter-interactive-wrapper:focus-visible {
  outline: 2px solid var(--gold2);
  outline-offset: 6px;
  border-radius: 8px;
}

.hunter-art {
  width: min(100%, 360px);
  max-height: 60vh;
  object-fit: contain;
  filter: drop-shadow(0 14px 45px rgba(0, 0, 0, 0.85))
    drop-shadow(0 0 25px rgba(197, 160, 89, 0.25));
  animation: float 7s ease-in-out infinite;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
}

/* Hunter Dialogue Cloud */
.hunter-dialogue-panel {
  position: absolute;
  bottom: calc(100% - 10px);
  right: -10px;
  width: min(90vw, 360px);
  background: rgba(18, 15, 22, 0.97);
  border: 1px solid var(--gold);
  border-radius: 6px;
  padding: 16px 20px;
  box-shadow:
    0 16px 40px rgba(0, 0, 0, 0.9),
    0 0 25px rgba(197, 160, 89, 0.35);
  backdrop-filter: blur(16px);
  z-index: 20;
  animation: fadeIn 0.3s ease-out;
}

.hunter-dialogue-panel::after {
  content: "";
  position: absolute;
  bottom: -8px;
  right: 60px;
  width: 14px;
  height: 14px;
  background: rgba(18, 15, 22, 0.97);
  border-right: 1px solid var(--gold);
  border-bottom: 1px solid var(--gold);
  transform: rotate(45deg);
}

/* 2. Interactive Golden Book - Foreground Composition */
.book-interactive-wrapper {
  position: absolute;
  bottom: 12px;
  left: clamp(-90px, -7vw, -30px);
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
  z-index: 12; /* In front of hunter artwork and background */
}

.hero-book {
  width: clamp(210px, 24vw, 290px);
  max-height: 42vh;
  object-fit: contain;
  opacity: 0.98;
  filter: drop-shadow(0 14px 34px rgba(0, 0, 0, 0.9)) drop-shadow(0 0 20px rgba(197, 160, 89, 0.4));
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.book-interactive-wrapper:hover .hero-book,
.book-interactive-wrapper:focus-visible .hero-book {
  transform: translateY(-8px) scale(1.05) rotate(-1.5deg);
