/* Hero Visual Identity Art & Interactive Elements */
.hero-art {
  position: relative;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 520px;
  gap: 20px;
}

.hero-duo-container {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: clamp(16px, 3vw, 36px);
  position: relative;
  width: 100%;
}

/* 1. Interactive Hunter */
.hunter-interactive-wrapper {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
}

.hunter-interactive-wrapper:hover .hunter-art,
.hunter-interactive-wrapper:focus-visible .hunter-art {
  filter: drop-shadow(0 18px 50px rgba(0, 0, 0, 0.95))
    drop-shadow(0 0 32px rgba(240, 213, 154, 0.65)) drop-shadow(0 0 50px rgba(139, 30, 45, 0.35));
  transform: translateY(-6px) scale(1.02);
}

.hunter-interactive-wrapper:focus-visible {
  outline: 2px solid var(--gold2);
  outline-offset: 6px;
  border-radius: 8px;
}

.hunter-art {
  width: min(100%, 360px);
  max-height: 60vh;
  object-fit: contain;
  filter: drop-shadow(0 14px 45px rgba(0, 0, 0, 0.85))
    drop-shadow(0 0 25px rgba(197, 160, 89, 0.25));
  animation: float 7s ease-in-out infinite;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
  z-index: 3;
}

/* Hunter Dialogue Cloud */
.hunter-dialogue-panel {
  position: absolute;
  bottom: calc(100% - 20px);
  right: -20px;
  width: min(90vw, 380px);
  background: rgba(18, 15, 22, 0.96);
  border: 1px solid var(--gold);
  border-radius: 6px;
  padding: 18px 22px;
  box-shadow:
    0 16px 40px rgba(0, 0, 0, 0.9),
    0 0 25px rgba(197, 160, 89, 0.35);
  backdrop-filter: blur(16px);
  z-index: 10;
  animation: fadeIn 0.3s ease-out;
}

.hunter-dialogue-panel::after {
  content: "";
  position: absolute;
  bottom: -8px;
  left: 60px;
  width: 14px;
  height: 14px;
  background: rgba(18, 15, 22, 0.96);
  border-right: 1px solid var(--gold);
  border-bottom: 1px solid var(--gold);
  transform: rotate(45deg);
}

/* 2. Interactive Golden Book */
.book-interactive-wrapper {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
  z-index: 4;
}

.hero-book {
  width: min(36vw, 240px);
  max-height: 40vh;
  object-fit: contain;
  opacity: 0.98;
  filter: drop-shadow(0 12px 30px rgba(0, 0, 0, 0.9)) drop-shadow(0 0 16px rgba(197, 160, 89, 0.35));
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.book-interactive-wrapper:hover .hero-book,
.book-interactive-wrapper:focus-visible .hero-book {
  transform: translateY(-8px) scale(1.06) rotate(-2deg);
  filter: drop-shadow(0 18px 45px rgba(0, 0, 0, 0.95))
    drop-shadow(0 0 32px rgba(240, 213, 154, 0.75));
}

.book-interactive-wrapper:focus-visible {
  outline: 2px solid var(--gold2);
  outline-offset: 6px;
  border-radius: 8px;
}

.book-hover-label {
  margin-top: 8px;
  font-family: var(--display);
  font-size: 11px;
  color: var(--gold2);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: rgba(13, 13, 17, 0.88);
  border: 1px solid rgba(197, 160, 89, 0.4);
  padding: 4px 10px;
  border-radius: 3px;
  white-space: nowrap;
  pointer-events: none;
  transition: all 0.25s ease;
}

.book-interactive-wrapper:hover .book-hover-label,
.book-interactive-wrapper:focus-visible .book-hover-label {
  border-color: var(--gold2);
  background: rgba(35, 20, 26, 0.95);
  box-shadow: 0 0 12px rgba(197, 160, 89, 0.4);
}

/* Emerging Words Animation from the Golden Book */
@keyframes emergeWord {
  0% {
    opacity: 0;
    transform: translate(0, 0) scale(0.85);
  }
  20% {
    opacity: 0.95;
  }
  80% {
    opacity: 0.75;
    transform: translate(var(--dx, 12px), -55px) scale(1.05);
  }
  100% {
    opacity: 0;
    transform: translate(var(--dx, 20px), -85px) scale(1.1);
  }
}

.emerging-word {
  position: absolute;
  font-family: var(--display);
  font-size: 11px;
  color: var(--gold2);
  letter-spacing: 0.12em;
  text-shadow:
    0 0 10px rgba(197, 160, 89, 0.85),
    0 0 18px rgba(240, 213, 154, 0.45);
  pointer-events: none;
  animation: emergeWord 4.8s ease-out infinite;
  white-space: nowrap;
  z-index: 6;
}

@media (max-width: 900px) {
  .hero-art {
    min-height: 380px;
    margin-top: 24px;
    width: 100%;
  }
  .hero-duo-container {
    flex-direction: row;
    align-items: center;
    gap: 16px;
  }
  .hunter-art {
    max-height: 340px;
    width: min(50vw, 260px);
  }
  .hero-book {
    width: min(40vw, 190px);
    max-height: 240px;
  }
  .hunter-dialogue-panel {
    right: 0;
    left: 0;
    width: 95%;
    margin: 0 auto;
    bottom: calc(100% + 10px);
  }
}

