/* Hero Visual Identity Art & Interactive Elements */
.hero-art {
  position: relative;
  z-index: 5;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: 520px;
  width: 100%;
}

.hero-duo-container {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  position: relative;
  width: 100%;
  min-height: 500px;
  gap: clamp(20px, 3.5vw, 56px);
}

/* 1. Central Interactive Golden Book */
.book-interactive-wrapper {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
  z-index: 10;
  margin-bottom: 6px;
}

.hero-book {
  width: clamp(290px, 32vw, 420px);
  max-height: 52vh;
  object-fit: contain;
  opacity: 0.98;
  filter: drop-shadow(0 16px 36px rgba(0, 0, 0, 0.95))
    drop-shadow(0 0 24px rgba(197, 160, 89, 0.45));
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.book-interactive-wrapper:hover .hero-book,
.book-interactive-wrapper:focus-visible .hero-book {
