    drop-shadow(0 0 38px rgba(240, 213, 154, 0.85));
}

.book-interactive-wrapper:focus-visible {
  outline: 2px solid var(--gold2);
  outline-offset: 6px;
  border-radius: 8px;
}

.book-hover-label {
  margin-top: 10px;
  font-family: var(--display);
  font-size: 11px;
  color: var(--gold2);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: rgba(13, 13, 17, 0.92);
  border: 1px solid rgba(197, 160, 89, 0.45);
  padding: 5px 14px;
  border-radius: 3px;
  white-space: nowrap;
  pointer-events: none;
  transition: all 0.25s ease;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.7);
}

.book-interactive-wrapper:hover .book-hover-label,
.book-interactive-wrapper:focus-visible .book-hover-label {
  border-color: var(--gold2);
  background: rgba(35, 20, 26, 0.95);
  box-shadow: 0 0 16px rgba(197, 160, 89, 0.5);
}

/* Emerging Words Animation from the Golden Book - Contained Container */
.emerging-words-container {
  position: absolute;
  top: 16%;
  left: 50%;
  transform: translateX(-50%);
  width: min(85%, 260px);
  height: 105px;
  overflow: hidden; /* Clips overflow strictly within this container! */
  pointer-events: none;
  z-index: 14;
}

@keyframes emergeWordContained {
  0% {
    opacity: 0;
    transform: translate(-50%, 85px) scale(0.85);
  }
  20% {
    opacity: 0.95;
  }
  75% {
    opacity: 0.85;
    transform: translate(calc(-50% + var(--dx, 8px)), 28px) scale(1.02);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--dx, 12px)), 4px) scale(1.04);
  }
}

.emerging-word {
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  font-family: var(--display);
  font-size: 11px;
  color: var(--gold2);
  letter-spacing: 0.14em;
  text-shadow:
    0 0 10px rgba(197, 160, 89, 0.85),
    0 0 18px rgba(240, 213, 154, 0.45);
  pointer-events: none;
  animation: emergeWordContained 5.2s ease-out infinite;
  white-space: nowrap;
}

/* 2. Interactive Hunter - Narrator Positioned to the Right of the Book */
.hunter-interactive-wrapper {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
  z-index: 5;
  margin-bottom: 6px;
}

.hunter-interactive-wrapper:hover .hunter-art,
.hunter-interactive-wrapper:focus-visible .hunter-art {
  filter: drop-shadow(0 18px 50px rgba(0, 0, 0, 0.95))
    drop-shadow(0 0 32px rgba(240, 213, 154, 0.65)) drop-shadow(0 0 50px rgba(139, 30, 45, 0.35));
  transform: translateY(-6px) scale(1.02);
}

.hunter-interactive-wrapper:focus-visible {
  outline: 2px solid var(--gold2);
  outline-offset: 6px;
  border-radius: 8px;
}

.hunter-art {
  width: clamp(210px, 22vw, 300px);
  max-height: 48vh;
  object-fit: contain;
  filter: drop-shadow(0 14px 40px rgba(0, 0, 0, 0.85))
    drop-shadow(0 0 20px rgba(197, 160, 89, 0.25));
  animation: float 7s ease-in-out infinite;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
  opacity: 0.95;
}

/* Hunter Dialogue Panel - Completely Within Viewport, Never Clipped */
.hunter-dialogue-panel {
  position: absolute;
  top: 10px;
  right: calc(100% + 14px);
  width: min(85vw, 340px);
  max-height: 270px;
  background: rgba(18, 15, 22, 0.98);
  border: 1px solid var(--gold);
  border-radius: 6px;
  padding: 14px 16px;
  box-shadow:
    0 16px 40px rgba(0, 0, 0, 0.95),
    0 0 25px rgba(197, 160, 89, 0.35);
  backdrop-filter: blur(16px);
  z-index: 25;
  animation: fadeIn 0.3s ease-out;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

.hunter-dialogue-panel::after {
  content: "";
  position: absolute;
  top: 24px;
  right: -6px;
  width: 11px;
  height: 11px;
  background: rgba(18, 15, 22, 0.98);
  border-right: 1px solid var(--gold);
  border-top: 1px solid var(--gold);
  transform: rotate(45deg);
}

.hunter-dialogue-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(197, 160, 89, 0.3);
  padding-bottom: 6px;
  margin-bottom: 8px;
  gap: 8px;
  flex-shrink: 0;
}

.hunter-sound-btn {
  background: rgba(197, 160, 89, 0.15);
  border: 1px solid var(--gold);
  border-radius: 3px;
  color: var(--gold2);
  cursor: pointer;
  font-size: 10.5px;
  padding: 2px 6px;
  font-family: var(--mono);
  display: flex;
  align-items: center;
  gap: 3px;
}

.hunter-dialogue-body {
  flex: 1 1 auto;
  overflow-y: auto;
  min-height: 0;
  padding-right: 4px;
  font-family: var(--serif);
  font-size: 13.5px;
  line-height: 1.5;
  color: #f7ebd2;
  white-space: pre-line;
  word-break: break-word;
  font-style: italic;
  scrollbar-width: thin;
  scrollbar-color: var(--gold) transparent;
}

.hunter-dialogue-body::-webkit-scrollbar {
  width: 4px;
}
.hunter-dialogue-body::-webkit-scrollbar-thumb {
  background: var(--gold);
  border-radius: 2px;
}

.hunter-dialogue-footer {
  margin-top: 8px;
  border-top: 1px dashed rgba(197, 160, 89, 0.25);
  padding-top: 6px;
  font-size: 10px;
  font-family: var(--mono);
  color: var(--gold2);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-shrink: 0;
}

@media (max-width: 900px) {
  .hero-art {
    min-height: auto;
    margin-top: 28px;
    width: 100%;
    justify-content: center;
  }
  .hero-duo-container {
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 24px;
    min-height: auto;
  }
  .hunter-art {
    max-height: 320px;
    width: min(70vw, 260px);
  }
  .hero-book {
    width: min(80vw, 320px);
    max-height: 280px;
  }
  .hunter-dialogue-panel {
    position: relative;
    top: 0;
    right: 0;
    left: 0;
    width: 100%;
    max-width: 380px;
    margin: 12px auto 0;
  }
  .hunter-dialogue-panel::after {
    display: none;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  .emerging-word {
    animation: none !important;
    display: none !important;
  }
}

