.book-interactive-wrapper {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
  z-index: 10;
  margin-bottom: 8px;
}

.hero-book {
  width: clamp(170px, 16vw, 220px);
  max-height: 145px;
  object-fit: contain;
  opacity: 0.98;
  filter: drop-shadow(0 12px 28px rgba(0, 0, 0, 0.95))
    drop-shadow(0 0 20px rgba(197, 160, 89, 0.45));
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.book-interactive-wrapper:hover .hero-book,
.book-interactive-wrapper:focus-visible .hero-book {
  transform: translateY(-6px) scale(1.04) rotate(-1deg);
  filter: drop-shadow(0 18px 40px rgba(0, 0, 0, 0.98))
    drop-shadow(0 0 30px rgba(240, 213, 154, 0.8));
}

.book-interactive-wrapper:focus-visible {
  outline: 2px solid var(--gold2);
  outline-offset: 6px;
  border-radius: 8px;
}

.book-hover-label {
  margin-top: 8px;
  font-family: var(--display);
  font-size: 10px;
  color: var(--gold2);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: rgba(13, 13, 17, 0.92);
  border: 1px solid rgba(197, 160, 89, 0.45);
  padding: 4px 11px;
  border-radius: 3px;
  white-space: nowrap;
  pointer-events: none;
  transition: all 0.25s ease;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.7);
}

.book-interactive-wrapper:hover .book-hover-label,
.book-interactive-wrapper:focus-visible .book-hover-label {
  border-color: var(--gold2);
  background: rgba(35, 20, 26, 0.95);
  box-shadow: 0 0 16px rgba(197, 160, 89, 0.5);
}

/* Emerging Words Animation from the Golden Book - Contained Container */
.emerging-words-container {
  position: absolute;
  top: 12%;
  left: 50%;
  transform: translateX(-50%);
  width: min(85%, 180px);
  height: 65px;
  overflow: hidden; /* Clips overflow strictly within this container! */
  pointer-events: none;
  z-index: 14;
}

@keyframes emergeWordContained {
  0% {
    opacity: 0;
    transform: translate(-50%, 55px) scale(0.85);
  }
  20% {
    opacity: 0.95;
  }
  75% {
    opacity: 0.85;
    transform: translate(calc(-50% + var(--dx, 6px)), 18px) scale(1.01);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--dx, 8px)), 2px) scale(1.02);
  }
}

.emerging-word {
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  font-family: var(--display);
  font-size: 9.5px;
  color: var(--gold2);
  letter-spacing: 0.12em;
  text-shadow:
    0 0 8px rgba(197, 160, 89, 0.85),
    0 0 14px rgba(240, 213, 154, 0.45);
  pointer-events: none;
  animation: emergeWordContained 5.2s ease-out infinite;
  white-space: nowrap;
}

/* 2. Interactive Hunter - Narrator Positioned to the Right of the Book */
.hunter-interactive-wrapper {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
  z-index: 20;
  margin-bottom: 6px;
}

.hunter-interactive-wrapper:hover .hunter-art,
.hunter-interactive-wrapper:focus-visible .hunter-art {
  filter: drop-shadow(0 18px 50px rgba(0, 0, 0, 0.95))
    drop-shadow(0 0 32px rgba(240, 213, 154, 0.65)) drop-shadow(0 0 50px rgba(139, 30, 45, 0.35));
  transform: translateY(-6px) scale(1.02);
}

.hunter-interactive-wrapper:focus-visible {
  outline: 2px solid var(--gold2);
  outline-offset: 6px;
  border-radius: 8px;
}

.hunter-art {
  width: clamp(180px, 18vw, 230px);
  max-height: 440px;
  object-fit: contain;
  filter: drop-shadow(0 14px 40px rgba(0, 0, 0, 0.85))
    drop-shadow(0 0 20px rgba(197, 160, 89, 0.25));
  animation: float 7s ease-in-out infinite;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
  opacity: 0.95;
}

/* Hunter Dialogue Panel - Positioned Above the Book with Zero Overlap */
.hunter-dialogue-panel {
  position: absolute;
  top: 15px;
  right: calc(100% + 14px);
  width: min(85vw, 310px);
  max-height: 200px;
  background: rgba(18, 15, 22, 0.98);
  border: 1px solid var(--gold);
  border-radius: 6px;
  padding: 10px 14px;
  box-shadow:
    0 16px 40px rgba(0, 0, 0, 0.95),
    0 0 25px rgba(197, 160, 89, 0.35);
  backdrop-filter: blur(16px);
  z-index: 25;
  animation: fadeIn 0.3s ease-out;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

.hunter-dialogue-panel::after {
  content: "";
  position: absolute;
  top: 24px;
  right: -6px;
  width: 11px;
  height: 11px;
  background: rgba(18, 15, 22, 0.98);
  border-right: 1px solid var(--gold);
  border-top: 1px solid var(--gold);
  transform: rotate(45deg);
}

.hunter-dialogue-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(197, 160, 89, 0.3);
  padding-bottom: 6px;
  margin-bottom: 6px;
  gap: 8px;
  flex-shrink: 0;
}

.hunter-sound-btn {
  background: rgba(197, 160, 89, 0.15);
  border: 1px solid var(--gold);
  border-radius: 3px;
  color: var(--gold2);
  cursor: pointer;
  font-size: 10px;
  padding: 2px 6px;
  font-family: var(--mono);
  display: flex;
  align-items: center;
  gap: 3px;
}

.hunter-dialogue-body {
  flex: 1 1 auto;
  overflow-y: auto;
  min-height: 0;
  padding-right: 4px;
  font-family: var(--serif);
  font-size: 12.5px;
  line-height: 1.45;
  color: #f7ebd2;
  white-space: pre-line;
  word-break: break-word;
  font-style: italic;
  scrollbar-width: thin;
  scrollbar-color: var(--gold) transparent;
}

.hunter-dialogue-body::-webkit-scrollbar {
  width: 4px;
}
.hunter-dialogue-body::-webkit-scrollbar-thumb {
  background: var(--gold);
  border-radius: 2px;
}

.hunter-dialogue-footer {
  margin-top: 6px;
  border-top: 1px dashed rgba(197, 160, 89, 0.25);
  padding-top: 5px;
  font-size: 9.5px;
  font-family: var(--mono);
  color: var(--gold2);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-shrink: 0;
}

@media (max-width: 900px) {
  .hero-art {
    min-height: auto;
    margin-top: 28px;
    width: 100%;
    justify-content: center;
  }
  .hero-duo-container {
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 20px;
    min-height: auto;
  }
  .hunter-art {
    max-height: 280px;
    width: min(70vw, 200px);
  }
  .hero-book {
    width: min(70vw, 190px);
    max-height: 130px;
  }
  .hunter-dialogue-panel {
    position: relative;
    top: 0;
    right: 0;
    left: 0;
    width: 100%;
    max-width: 360px;
    margin: 10px auto 0;
  }
  .hunter-dialogue-panel::after {
    display: none;
  }
}

